// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bool reentered;
    uint256 reentryAmt;

    function setUp() public { c = new C(address(new Log())); }

    receive() external payable {
        if (!reentered && reentryAmt > 0) {
            reentered = true;
            // re-entrant withdrawal attempt; low-level call so failures don't bubble here
            address(c).call(abi.encodeWithSignature("CashOut(uint256)", reentryAmt));
        }
    }

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        deposit = bound(deposit, 1.0001 ether, 1e24 ether);
        // amount is a legitimate withdrawal: does not exceed the deposited balance,
        // but is more than half of it -> distinguishes check-effects-interaction order
        amount = bound(amount, deposit / 2 + 1, deposit);
        vm.assume(amount <= deposit && 2 * amount > deposit);

        reentered = false;
        reentryAmt = amount;

        vm.deal(address(this), deposit);
        (bool depOk, ) = address(c).call{value: deposit}(abi.encodeWithSignature("Deposit()"));
        assertTrue(depOk);
        assertTrue(c.balances(address(this)) == deposit);

        // Rule: withdrawing amount <= balance always succeeds.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", amount));
        assertTrue(ok);
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c)
    {
        c = _c;
    }

    function test(uint amt) public
    {
        require(amt > c.MinDeposit());
        require(address(this).balance >= amt);
        c.Deposit{value: amt}();
        assert(c.balances(address(this)) == amt);
    }

    receive() external payable {}

    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint a1, uint a2) public {
        require(address(this).balance >= a1 + a2 + 2 ether);
        c.Deposit{value: a1 + 2 ether}();
        c.Deposit{value: a2 + 2 ether}();
        assert(c.balances(address(this)) == (a1 + 2 ether) + (a2 + 2 ether));
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(tx.origin != address(this));
        require(amount > c.MinDeposit());
        uint originBalBefore = c.balances(tx.origin);
        c.Deposit{value: amount}();
        assert(c.balances(tx.origin) == originBalBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint a1, uint a2) public {
        require(a1 + a2 <= type(uint256).max - 4 ether);
        require(address(this).balance >= a1 + a2 + 2 ether + 2 ether);
        c.Deposit{value: a1 + 2 ether}();
        c.Deposit{value: a2 + 2 ether}();
        assert(c.balances(address(this)) == (a1 + 2 ether) + (a2 + 2 ether));
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint a1, uint a2) public {
        require(a1 + a2 <= type(uint256).max - 4 ether);
        require(a1 + a2 + 4 ether <= type(uint256).max / 2);
        require(address(this).balance >= a1 + a2 + 2 ether + 2 ether);
        c.Deposit{value: a1 + 2 ether}();
        c.Deposit{value: a2 + 2 ether}();
        assert(c.balances(address(this)) == (a1 + 2 ether) + (a2 + 2 ether));
    }
    receive() external payable {}
    fallback() external payable {}
}
